import json,hashlib
from pathlib import Path
p=Path(__file__).resolve().parents[1]
labels={'K0':'rooted dual','K1':'balanced incidence','K2':'disjoint pair','K3':'disk identity','K4':'reversal signs','K5':'positive circulation','K6':'fixed-s cancellation','K7':'nonvanishing','K8':'forest state / H-s','K10':'white cotree','K11':'selected matching','K12':'Hamiltonian / induced trees','K15':'separator gluing','K16':'edge-avoidance theorem'}
routes=[('FederSubi','K12','colour-restricted induced tree; proved dictionary'),('BagheriParity','K2','NOT equivalent; truncated-octahedron counterexample'),('Goodey','K16','earlier four/six result; original proof unavailable'),('Kardos','K12','resonant flips and residual tree; analogy only'),('Schnieders','K15','boundary-pattern compatibility; different substitutions'),('Stein','K12','region B-sets; historical equivalence'),('APSW','K12','Lemma 5 exact equivalence'),('KelmansHertel','K15','cyclic four-connectivity reduction'),('KelmansHertel','K16','edge prescriptions'),('GSW','K16','Pfaffian P4 consequence via equivalence'),('TuttePaths','K15','attachment interfaces; analogy only'),('Grinberg','K3','Euler boundary counts; missing state equality'),('HMM_BGM','K16','finite verification, not existence mechanism'),('TutteTrinity','K1','single incidence states'),('Berman','K1','single-state determinant'),('HineKalman','K1','state convention and clock moves'),('DoubleDimer','K7','union-cycle regrouping, not full nonvanishing'),('PlaneDuality','K10','complementary tree theorem')]
s=['digraph older_routes {','rankdir=LR;','node [shape=box];']+[f'{k} [label="{k}: {v}"];' for k,v in labels.items()]
for a,b,l in routes:s.append(f'{a} -> {b} [label="{l}", style={"dashed" if "analogy" in l or "NOT" in l else "solid"}];')
for a,b in [('K0','K1'),('K1','K2'),('K0','K3'),('K3','K4'),('K4','K6'),('K4','K7'),('K5','K7'),('K2','K7'),('K6','K8'),('K7','K8'),('K8','K10'),('K10','K11'),('K11','K12'),('K12','K16'),('K15','K16')]:s.append(f'{a} -> {b} [color=gray];')
s.append('}');(p/'older-routes.dot').write_text('\n'.join(s))
files=list((p/'text').glob('*'))
(p/'code/source-manifest.json').write_text(json.dumps([dict(file=f.name,bytes=f.stat().st_size,sha256=hashlib.sha256(f.read_bytes()).hexdigest()) for f in files],indent=2))
(p/'knowledge.json').write_text(json.dumps({'nodes':[{'id':'parity-identification','tier':2,'status':'refuted','review':'unreviewed','evidence':'BRIDGES.md#1-feder–subi-and-spanning-trees-of-faces'},{'id':'chain-cmin','tier':2,'status':'proved-here','review':'unreviewed','evidence':'BRIDGES.md'},{'id':'pfaffian-direct','status':'open','evidence':'BRIDGES.md'},{'id':'census','tier':4,'status':'computed','review':'unreviewed','evidence':'code/results.json'}]},indent=2))
(p/'frontier.json').write_text(json.dumps({'census':json.loads((p/'code/results.json').read_text())['census'],'open':['separator-free Goodey c_min bound','canonical forest rule','Pfaffian incidence replacement','full historical novelty search']},indent=2))
print('map, manifest and local handoff data written')
